script:
frappe.ui.form.on('Quotation', {
    custom_service: function (frm) {
        frm.set_query('custom_service_template', function () {
            return {
                filters: {
                    service_type: frm.doc.custom_service
                }
            };
        });
    }
});

frappe.ui.form.on('Quotation', {
    custom_service_type: function (frm) {
        console.log("Service Type changed:", frm.doc.custom_service_type);

        // Reset only these fields
        frm.set_value('custom_service_template', null);
        frm.set_value('custom_document_type', null);

        // Add a filter to Service Template
        frm.set_query('custom_service_template', function () {
            return {
                filters: {
                    service_type: frm.doc.custom_service_type
                }
            };
        });

        // Ensure Business Name is untouched
        console.log("Business Name remains:", frm.doc.custom_business_name);
    }
});

frappe.ui.form.on('Service Charge Item', {
    item: function (frm, cdt, cdn) {
        const row = locals[cdt][cdn];
        if (row.item) {
            frappe.db.get_value('Item Price', { item_code: row.item, price_list: 'Standard Selling' }, 'price_list_rate', (r) => {
                if (r && r.price_list_rate) {
                    frappe.model.set_value(cdt, cdn, 'cost', r.price_list_rate); // Set the cost field in the child table
                } else {
                    frappe.model.set_value(cdt, cdn, 'cost', 0); // Set cost to 0 if no price is found
                }
            });
        }
    }
});

frappe.ui.form.on('Quotation', {
    onload_post_render: function (frm) {
        frm.set_df_property("custom_business_name", "hidden", true);
        frm.set_df_property("custom_personnel_name", "hidden", true);
        frm.set_df_property("custom_service_for", "hidden", true); // Hide on load
    },
    quotation_to: function (frm) {
        if (["Business", "Personnel"].includes(frm.doc.quotation_to)) {
            if (frm.doc.quotation_to === "Business") {
                frm.set_df_property("custom_business_name", "reqd", true);
                frm.set_df_property("custom_business_name", "hidden", false);
                frm.set_df_property("custom_personnel_name", "reqd", false);
                frm.set_df_property("custom_personnel_name", "hidden", true);
                frm.set_value("custom_personnel_name", null); // Clear non-required field
            } else if (frm.doc.quotation_to === "Personnel") {
                frm.set_df_property("custom_personnel_name", "reqd", true);
                frm.set_df_property("custom_personnel_name", "hidden", false);
                frm.set_df_property("custom_business_name", "reqd", false);
                frm.set_df_property("custom_business_name", "hidden", true);
                frm.set_value("custom_business_name", null); // Clear non-required field
            }
        } else {
            frm.set_df_property("custom_business_name", "hidden", true);
            frm.set_df_property("custom_personnel_name", "hidden", true);
        }
    },
    custom_document_type: function (frm) {
        if (frm.doc.custom_document_type === "Individual Document") {
            frm.set_df_property("custom_service_for", "hidden", false);
        } else {
            frm.set_df_property("custom_service_for", "hidden", true);
            frm.set_value("custom_service_for", ""); // Clear value when hidden
        }
    },
    custom_business_name: function (frm) {
        frm.trigger("fetch_personnel_list");
    },
    fetch_personnel_list: function (frm) {
        // Fetch Personnel only when Business Name is selected
        if (frm.doc.custom_business_name && frm.doc.custom_document_type === "Individual Document") {
            frappe.call({
                method: "frappe.client.get_list",
                args: {
                    doctype: "Personnel",
                    fields: ["name", "full_name"],
                    filters: {
                        business: frm.doc.custom_business_name
                    }
                },
                callback: function (response) {
                    if (response.message && response.message.length > 0) {
                        const personnel_options = response.message.map(person => ({
                            value: person.name,
                            label: person.full_name
                        }));

                        frm.set_df_property("custom_service_for", "options", personnel_options);
                        frm.refresh_field("custom_service_for");
                    } else {
                        frm.set_df_property("custom_service_for", "options", []); // Clear options
                        frm.set_value("custom_service_for", null); // Clear value
                        frm.refresh_field("custom_service_for");
                    }
                }
            });
        }
    }
});

frappe.ui.form.on('Quotation', {
    custom_service_template: function (frm) {
        if (frm.doc.custom_service_template && frm.doc.custom_service_for) {
            // Add a new row to the child table whenever both fields are filled
            frm.trigger('add_new_row_to_child_table');
        }
    },

    custom_service_for: function (frm) {
        if (frm.doc.custom_service_for && frm.doc.custom_service_template) {
            // Add a new row to the child table whenever both fields are filled
            frm.trigger('add_new_row_to_child_table');
        }
    },

    add_new_row_to_child_table: function (frm) {
        const serviceTemplate = frm.doc.custom_service_template;
        const serviceFor = frm.doc.custom_service_for;

        if (!serviceTemplate || !serviceFor) {
            frappe.msgprint(__('Please ensure both Service Template and Service For fields are filled.'));
            return;
        }

        // Add a new row to the child table
        let childRow = frm.add_child('custom_quotation_services');
        childRow.service = serviceTemplate;

        // Fetch the full name for the service_for field
        frappe.db.get_value('Personnel', serviceFor, 'full_name')
            .then(response => {
                if (response && response.message && response.message.full_name) {
                    let full_name = response.message.full_name;

                    // Update the new row with the full name
                    childRow.service_for = full_name;

                    // Refresh the child table to reflect changes
                    frm.refresh_field('custom_quotation_services');

                    // Clear the custom_service_for field for the next entry
                    frm.set_value('custom_service_for', null);
                } else {
                    frappe.msgprint(__('Failed to fetch Personnel details.'));
                }
            })
            .catch(err => {
                frappe.msgprint({
                    title: __('Error'),
                    message: __('Failed to fetch Personnel details: ' + err.message),
                    indicator: 'red',
                });
            });
    }
});

frappe.ui.form.on('Quotation', {
    onload_post_render: function (frm) {
        frm.set_df_property("custom_business_name", "hidden", true);
        frm.set_df_property("custom_personnel_name", "hidden", true);
        frm.set_df_property("custom_service_for", "hidden", true); // Hide on load
    },

    quotation_to: function (frm) {
        if (["Business", "Personnel"].includes(frm.doc.quotation_to)) {
            if (frm.doc.quotation_to === "Business") {
                frm.set_df_property("custom_business_name", "reqd", true);
                frm.set_df_property("custom_business_name", "hidden", false);
                frm.set_df_property("custom_personnel_name", "reqd", false);
                frm.set_df_property("custom_personnel_name", "hidden", true);
                frm.set_value("custom_personnel_name", null); // Clear non-required field
            } else if (frm.doc.quotation_to === "Personnel") {
                frm.set_df_property("custom_personnel_name", "reqd", true);
                frm.set_df_property("custom_personnel_name", "hidden", false);
                frm.set_df_property("custom_business_name", "reqd", false);
                frm.set_df_property("custom_business_name", "hidden", true);
                frm.set_value("custom_business_name", null); // Clear non-required field
            }
        } else {
            frm.set_df_property("custom_business_name", "hidden", true);
            frm.set_df_property("custom_personnel_name", "hidden", true);
        }
    },

    custom_document_type: function (frm) {
        if (frm.doc.custom_document_type === "Individual Document") {
            frm.set_df_property("custom_service_for", "hidden", false);
        } else {
            frm.set_df_property("custom_service_for", "hidden", true);
            frm.set_value("custom_service_for", ""); // Clear value when hidden
        }
    },

    custom_business_name: function (frm) {
        frm.trigger("fetch_personnel_list");
    },

    fetch_personnel_list: function (frm) {
        if (frm.doc.custom_business_name && frm.doc.custom_document_type === "Individual Document") {
            frappe.call({
                method: "frappe.client.get_list",
                args: {
                    doctype: "Personnel",
                    fields: ["name", "full_name"],
                    filters: {
                        business: frm.doc.custom_business_name
                    }
                },
                callback: function (response) {
                    if (response.message && response.message.length > 0) {
                        const personnel_options = response.message.map(person => ({
                            value: person.name,
                            label: person.full_name
                        }));

                        frm.set_df_property("custom_service_for", "options", personnel_options);
                        frm.refresh_field("custom_service_for");
                    } else {
                        frm.set_df_property("custom_service_for", "options", []); // Clear options
                        frm.set_value("custom_service_for", null); // Clear value
                        frm.refresh_field("custom_service_for");
                    }
                }
            });
        }
    },

    custom_service: function (frm) {
        frm.set_query('custom_service_template', function () {
            return {
                filters: {
                    service_type: frm.doc.custom_service
                }
            };
        });
    },

    custom_service_template: function (frm) {
        if (frm.doc.custom_service_template && frm.doc.custom_service_for) {
            frm.trigger('append_to_quotation_services');
        }
    },

    custom_service_for: function (frm) {
        if (frm.doc.custom_service_for && frm.doc.custom_service_template) {
            frm.trigger('append_to_quotation_services');
        }
    },

    append_to_quotation_services: function (frm) {
        const serviceTemplate = frm.doc.custom_service_template;
        const serviceFor = frm.doc.custom_service_for;

        if (serviceTemplate && serviceFor) {
            // Fetch full name for Service For
            frappe.db.get_value('Personnel', serviceFor, 'full_name')
                .then(response => {
                    if (response && response.message && response.message.full_name) {
                        let full_name = response.message.full_name;

                        // Add row to Quotation Services
                        let new_service_row = frm.add_child('custom_quotation_services');
                        new_service_row.service = serviceTemplate;
                        new_service_row.service_for = full_name; // Set full name in Quotation Services
                        new_service_row.custom_service_template = serviceTemplate; // Set template in Quotation Services
                        frm.refresh_field('custom_quotation_services');

                        // Add corresponding entry to the Items table
                        frappe.call({
                            method: "frappe.client.get",
                            args: {
                                doctype: "Service Template",
                                name: serviceTemplate
                            },
                            callback: function (template_response) {
                                if (template_response.message) {
                                    const service_template_data = template_response.message;

                                    (service_template_data.service_charge_item || []).forEach(row => {
                                        const new_item_row = frm.add_child("items");

                                        new_item_row.item_code = row.item_code;
                                        new_item_row.item_name = row.item_name;
                                        new_item_row.qty = row.quantity;
                                        new_item_row.rate = row.rate;
                                        new_item_row.amount = row.amount;
                                        new_item_row.uom = row.uom;
                                        new_item_row.custom_service = serviceTemplate; // Set template in Items
                                        new_item_row.custom_service_for = full_name; // Set full name in Items
                                        new_item_row.description = row.description;
                                        new_item_row.remarks = row.remarks;
                                    });

                                    frm.refresh_field("items");
                                    update_totals(frm);
                                }
                            }
                        });
                    } else {
                        frappe.msgprint(__('Failed to fetch Personnel details.'));
                    }
                })
                .catch(err => {
                    frappe.msgprint({
                        title: __('Error'),
                        message: __('Failed to fetch Personnel details: ' + err.message),
                        indicator: 'red',
                    });
                });
        }
    },

    // Trigger to delete items when a service entry is removed
    custom_quotation_services_remove: function (frm, cdt, cdn) {
        let deleted_row = frappe.get_doc(cdt, cdn);
        if (deleted_row && deleted_row.service) {
            frm.doc.items = frm.doc.items.filter(item => item.custom_service !== deleted_row.service);
            frm.refresh_field('items');
        }
    }
});

function update_totals(frm) {
    let total_quantity = 0;
    let total_aed = 0;

    (frm.doc.items || []).forEach(item => {
        total_quantity += item.qty || 0;
        total_aed += item.amount || 0;
    });

    frm.set_value("total_qty", total_quantity);
    frm.set_value("total", total_aed);
}

frappe.ui.form.on('Service Charge Item', {
    quantity: function(frm, cdt, cdn) {
        calculate_amount(frm, cdt, cdn);
    },
    rate: function(frm, cdt, cdn) {
        calculate_amount(frm, cdt, cdn);
    }
});

function calculate_amount(frm, cdt, cdn) {
    // Get the current row
    let row = frappe.get_doc(cdt, cdn);

    // Ensure quantity and rate are present
    if (row.quantity && row.rate) {
        // Calculate the amount
        frappe.model.set_value(cdt, cdn, 'amount', row.quantity * row.rate);
    } else {
        // Default to 0 if either field is missing
        frappe.model.set_value(cdt, cdn, 'amount', 0);
    }
}

frappe.ui.form.on('Work', {
    linked_quotation: function (frm) {
        // Store current values of service and service_for
        const currentService = frm.doc.service;
        const currentServiceFor = frm.doc.service_for;

        if (frm.doc.linked_quotation) {
            frappe.call({
                method: 'frappe.client.get',
                args: {
                    doctype: 'Quotation',
                    name: frm.doc.linked_quotation
                },
                callback: function (response) {
                    if (response.message) {
                        // Extract services and service_for
                        const services = response.message.custom_quotation_services.map(row => row.service);
                        const services_for = response.message.custom_quotation_services.map(row => row.service_for);

                        // Remove duplicates using Set
                        const uniqueServices = Array.from(new Set(services));
                        const uniqueServicesFor = Array.from(new Set(services_for));

                        console.log('Unique Services:', uniqueServices);
                        console.log('Unique Service For:', uniqueServicesFor);

                        // Set options for service and service_for fields
                        frm.set_df_property('service', 'options', uniqueServices.join('\n'));
                        frm.set_df_property('service_for', 'options', uniqueServicesFor.join('\n'));

                        // Refresh fields to reflect updated options
                        frm.refresh_field('service');
                        frm.refresh_field('service_for');

                        // Re-set the previous values if they are part of the updated options
                        if (uniqueServices.includes(currentService)) {
                            frm.set_value('service', currentService);
                        } else {
                            frm.set_value('service', '');
                        }
                        if (uniqueServicesFor.includes(currentServiceFor)) {
                            frm.set_value('service_for', currentServiceFor);
                        } else {
                            frm.set_value('service_for', '');
                        }
                    }
                }
            });
        } else {
            // Clear dropdowns if no linked quotation is selected
            frm.set_df_property('service', 'options', '');
            frm.set_df_property('service_for', 'options', '');
            frm.set_value('service', '');
            frm.set_value('service_for', '');
        }
    },
    validate: function (frm) {
        // Ensure the values are saved in the document before save
        frm.doc.service = frm.doc.service || '';
        frm.doc.service_for = frm.doc.service_for || '';
    },
    onload: function (frm) {
        // Refresh fields on load to ensure retained values
        frm.refresh_field('service');
        frm.refresh_field('service_for');
    }
});

frappe.ui.form.on('Work', {
    service: function (frm) {
        // Clear current values in the service_task child table
        frm.clear_table('service_task');

        if (frm.doc.service) {
            frappe.call({
                method: 'frappe.client.get',
                args: {
                    doctype: 'Service Template',
                    name: frm.doc.service
                },
                callback: function (response) {
                    if (response.message) {
                        // Extract tasks from the service template's service_task child table
                        const serviceTasks = response.message.service_task;

                        // Iterate through tasks and add them to service_task child table
                        if (serviceTasks && serviceTasks.length > 0) {
                            serviceTasks.forEach(task => {
                                let newRow = frm.add_child('service_task');
                                newRow.task = task.subject;
                                newRow.task_type = task.task_type;
                                newRow.mode = task.mode;
                            });

                            // Refresh the service_task field to display updated rows
                            frm.refresh_field('service_task');
                        }
                    }
                }
            });
        } else {
            // If no service is selected, clear the table
            frm.clear_table('service_task');
            frm.refresh_field('service_task');
        }
    }
});

frappe.ui.form.on("Quotation", {
    refresh: function (frm) {
        // Remove "Sales Order" option after the dropdown is rendered
        setTimeout(() => {
            frm.remove_custom_button('Sales Order', 'Create');
        }, 100); // Delay to ensure the button is rendered before removing it

        // Remove all buttons if the status is "Complete"
        if (frm.doc.workflow_state === "Complete") {
            frm.clear_custom_buttons(); // Clears all custom buttons
        }

        // Add custom buttons for "Open" status
        if (frm.doc.workflow_state === "Open") {
            // Add "Sales Invoice" option to Create dropdown
            frm.add_custom_button(__('Sales Invoice'), function () {
                frappe.model.open_mapped_doc({
                    method: "erpnext.selling.doctype.quotation.quotation.make_sales_invoice",
                    frm: frm,
                    post_process: function (invoice) {
                        // Update custom field
                        invoice.custom_linked_quotation = frm.doc.name;
                    },
                });
            }, __('Create'));

            // Add "Work" option to Create dropdown
            frm.add_custom_button(__('Work'), function () {
                frappe.model.open_mapped_doc({
                    method: "your_app.your_module.quotation.make_work",
                    frm: frm,
                    post_process: function (work) {
                        // Update custom field
                        work.linked_quotation = frm.doc.name;
                    },
                });
            }, __('Create'));
        }
    }
});

frappe.ui.form.on('Quotation', {
    onload: function (frm) {
        setTimeout(() => {
            // Hide specific connections
            $("[data-doctype='Sales Order']").hide();
            $("[data-doctype='Auto Repeat']").hide();

            // Hide the labels for Sales Order and Auto Repeat
            $(".form-dashboard .form-link-title:contains('Sales Order')").parent().hide();
            $(".form-dashboard .form-link-title:contains('Subscription')").parent().hide();

            // Check remaining visible connections
            const visibleConnections = $(".form-dashboard .row").filter(function () {
                return $(this).is(":visible");
            });

            // Hide the Connections header if no connections remain
            if (visibleConnections.length === 0) {
                $(".form-dashboard .section-head.collapsible").hide();
            } else {
                $(".form-dashboard .section-head.collapsible").show();
            }
        }, 10);
    }
});

frappe.ui.form.on('Quotation', {
    cancel: function (frm) {
        frappe.call({
            method: "docproc.document_processing_system.api.quotation.cancel_quotation",
            args: {
                docname: frm.doc.name
            },
            callback: function (r) {
                if (!r.exc) {
                    frappe.msgprint(__("Quotation has been cancelled successfully."));
                    frm.reload_doc();
                }
            }
        });
    }
});

frappe.ui.form.on("Quotation", {
    refresh: function (frm) {
        // Add "Set as Lost" button if applicable
        if (frm.doc.docstatus === 1 && frm.doc.status !== "Lost" && frm.doc.status !== "Ordered") {
            frm.add_custom_button(__("Set as Lost"), function () {
                frm.trigger("set_as_lost_dialog");
            });
        }
    },

    set_as_lost_dialog: function (frm) {
        // Create a dialog for setting the lost reason
        const dialog = new frappe.ui.Dialog({
            title: __("Set as Lost"),
            fields: [
                {
                    label: __("Lost Reason"),
                    fieldname: "lost_reason",
                    fieldtype: "Link",
                    options: "Quotation Lost Reason",
                    reqd: 1,
                },
                {
                    label: __("Competitor (Optional)"),
                    fieldname: "competitor",
                    fieldtype: "Data",
                },
                {
                    label: __("Detailed Reason (Optional)"),
                    fieldname: "detailed_reason",
                    fieldtype: "Text",
                },
            ],
            primary_action: function (data) {
                if (!data.lost_reason) {
                    frappe.throw(__("Please select a lost reason"));
                    return;
                }

                frappe.call({
                    method: "docproc.document_processing_system.api.quotation.set_as_lost",
                    args: {
                        quotation_name: frm.doc.name,
                        lost_reason: data.lost_reason,
                        competitor: data.competitor,
                        detailed_reason: data.detailed_reason,
                    },
                    callback: function (response) {
                        if (!response.exc) {
                            frm.reload_doc();
                            frappe.show_alert({ message: __("Quotation marked as lost"), indicator: "red" });
                        }
                    },
                });

                dialog.hide();
            },
            primary_action_label: __("Submit"),
        });

        dialog.show();
    },
});

frappe.ui.form.on('Quotation', {
    refresh: function (frm) {
        // Always hide the "Company" field
        frm.set_df_property('company', 'hidden', 1);

        // Define states for showing "Create" button
        const showCreateStates = ["To Work and Bill", "To Work", "To Bill"];

        // Ensure "Create" button visibility for specific states and docstatus
        setTimeout(() => {
            if (showCreateStates.includes(frm.doc.workflow_state) && frm.doc.docstatus === 1) {
                frm.page.wrapper.find('div[data-label="Create"]').show();
            } else {
                frm.page.wrapper.find('div[data-label="Create"]').hide();
            }
        }, 150);

        // Handle field properties based on workflow_state
        if (frm.doc.workflow_state === 'Cancelled') {
            // Make fields read-only
            frm.set_df_property('transaction_date', 'read_only', 1);
            frm.set_df_property('quotation_to', 'read_only', 1);
            frm.set_df_property('custom_service', 'read_only', 1);
            frm.set_df_property('custom_service_template', 'read_only', 1);
            set_read_only_for_service_fields(frm, 1); // Set read-only for any active service field
        } else {
            // Revert fields to editable for other states
            frm.set_df_property('transaction_date', 'read_only', 0);
            frm.set_df_property('quotation_to', 'read_only', 0);
            frm.set_df_property('custom_service', 'read_only', 0);
            frm.set_df_property('custom_service_template', 'read_only', 0);
            set_read_only_for_service_fields(frm, 0); // Revert to editable for any active service field
        }
    },
    workflow_state: function (frm) {
        // Trigger refresh to apply button and field visibility logic
        frm.trigger('refresh');
    }
});

// Helper Function to Handle Service Fields
function set_read_only_for_service_fields(frm, readOnly) {
    const serviceFields = [
        'custom_service_for_business',
        'custom_service_for_personnel',
        'custom_service_for_car_and_carrier'
    ];

    // Loop through the fields and set the read-only property
    serviceFields.forEach(field => {
        if (frm.fields_dict[field]) { // Check if the field exists in the form
            frm.set_df_property(field, 'read_only', readOnly);
        }
    });
}

frappe.ui.form.on('Quotation', {
    refresh: function (frm) {
        // Permanently hide the "Set as Lost" button
        setTimeout(() => {
            frm.page.wrapper.find('.custom-actions [data-label="Set%20as%20Lost"]').hide();
        }, 100);

        // Permanently hide the "Get Items From" button
        setTimeout(() => {
            frm.page.wrapper.find('.custom-actions [data-label="Get%20Items%20From"]').hide();
        }, 100);

        // Permanently hide the "Cancel" button
