function remove_items_not_in_services(frm) {
    const services = frm.doc.quotation_services || [];
    const updated_items = [];

    // Iterate over items and keep only those that match rows in quotation_services
    (frm.doc.items || []).forEach(item => {
        const is_valid = services.some(service => {
            return (
                service.service === item.custom_service &&
                (service.service_for === item.custom_service_for || service.full_name === item.custom_service_for)
            );
        });

        if (is_valid) {
            updated_items.push(item); // Keep valid items
        } else {
            console.log('Removing item:', item);
        }
    });

    // Replace the items table with only the valid items
    frm.doc.items = updated_items;

    // Refresh the items table
    frm.refresh_field('items');

    // Update totals
    update_totals(frm);
}

// Function to update the items table when custom_service_template or custom_service_for changes
function update_items_table(frm) {
    const service_template = frm.doc.custom_service_template;
    const service_for_id = frm.doc.custom_service_for;

    if (!service_template || !service_for_id) {
        return;
    }

    // Fetch full_name from Personnel Doctype
    frappe.call({
        method: "frappe.client.get",
        args: {
            doctype: "Personnel",
            name: service_for_id
        },
        callback: function (personnel_response) {
            if (personnel_response.message) {
                const full_name = personnel_response.message.full_name;

                // Fetch Service Template details
                frappe.call({
                    method: "frappe.client.get",
                    args: {
                        doctype: "Service Template",
                        name: service_template
                    },
                    callback: function (template_response) {
                        if (template_response.message) {
                            const service_template_data = template_response.message;

                            (service_template_data.service_charge_item || []).forEach(row => {
                                const new_row = frm.add_child("items");

                                // Populate item fields
                                new_row.item_code = row.item_code;
                                new_row.item_name = row.item_name;
                                new_row.qty = row.quantity;
                                new_row.rate = row.rate;
                                new_row.amount = row.amount;
                                new_row.uom = row.uom;

                                // Link to custom_service and custom_service_for
                                new_row.custom_service = service_template;
                                new_row.custom_service_for = full_name; // Use full_name instead of ID
                                new_row.description = row.description || '';
                                new_row.remarks = row.remarks || '';
                            });

                            frm.refresh_field("items");
                            update_totals(frm);
                        }
                    }
                });
            }
        }
    });
}

// Function to update totals
function update_totals(frm) {
    let total_quantity = 0;
    let total_amount = 0;

    // Recalculate totals
    (frm.doc.items || []).forEach(item => {
        total_quantity += item.qty || 0;
        total_amount += item.amount || 0;
    });

    frm.set_value('total_qty', total_quantity);
    frm.set_value('total', total_amount);
}

